head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.contnId = "";
scwin.attachIcon = "";
window.disPage = window.disPage || {};

// 첨부파일 다운로드(전역으로 선언)
window.disPage.fn_downloadAttach = function (contnId, contnAttachSeq) {
    scwin.downloadAttach(contnId, contnAttachSeq);
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — view 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {

        // 초기화함수

        scwin.init();

        scwin.view();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL58001.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출).
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    scwin.contnId = $c.data.getParameter("contnId");
    scwin.attachIcon = $c.data.getParameter("attachIcon");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_list_onclick
 * @description 목록 버튼 클릭 — 목록 화면으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_list_onclick = function (e) {
    try {
        $c.win.moveUrl(scwin.listUrl, dma_Req.getJSON());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL58001.btn_list_onclick" });
    }
};

/**
 * @method
 * @name btn_moveList_onclick
 * @description 「목록」 버튼 클릭 — 목록 화면으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_moveList_onclick = function (e) {
    try {
        const moveUrl = "/ui/lst/lstinvstg/ULDFIL58000.xml";
        $c.win.moveUrl(moveUrl);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL58001.btn_moveList_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name view
 * @description 공지사항/업무자료 상세를 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.view = async function () {

    dma_searchReq.set("contnId", scwin.contnId);

    const sbmOptions = {
        id : "sbm_selectViewContent",
        method: "get",
        action : "/api/listing/listinvstg/common-board/select-one",
        ref : "dma_searchReq",
        target : "dlt_bbsDetail=body",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res.responseJSON.success === true) {

        const resBody = res.responseJSON.body;

        tbx_contnTitle.setValue(resBody[0].contnTitle);
        tbx_regDdtm.setValue(resBody[0].regDdtm);
        txb_regContnContn.setValue(resBody[0].regContnContn);

        // 첨부파일
        if(Array.isArray(resBody) && resBody.length > 0) {

            let displayFileNm = "";
            for (let i = 0; i < resBody.length; i++) {
                const attachFileNm = resBody[i].attachFileNm;
                const contnId =  resBody[i].contnId;
                const contnAttachSeq =  resBody[i].contnAttachSeq;
                if(attachFileNm && attachFileNm !== "") {

                    let fileNm = `
                        <a href="javascript:void(0)"
                        style="margin:1px 1.5px;"
                        title="${attachFileNm}" 
                        onclick="window.disPage.fn_downloadAttach('${contnId}','${contnAttachSeq}')">
                    `;   

                    if(scwin.attachIcon === "1") {
                    fileNm += `<img src="/cm/images/dis/attach_1.gif" border="0" alt="${attachFileNm}">`;
                    } else if( scwin.attachIcon === "2") {
                    fileNm += `<img src="/cm/images/dis/attach_2.gif" border="0" alt="${attachFileNm}">`;
                    } else if( scwin.attachIcon === "3") {
                    fileNm += `<img src="/cm/images/dis/attach_3.gif" border="0" alt="${attachFileNm}">`;
                    } else if( scwin.attachIcon === "4") {
                    fileNm += `<img src="/cm/images/dis/attach_4.gif" border="0" alt="${attachFileNm}">`;
                    } else if( scwin.attachIcon === "6") {
                    fileNm += `<img src="/cm/images/dis/attach_6.gif" border="0" alt="${attachFileNm}">`;
                    } else {
                    fileNm += `<img src="/cm/images/dis/attach_5.gif" border="0" alt="${attachFileNm}">`;
                    }

                    fileNm += ` ${attachFileNm}</a></br>`;

                    displayFileNm += fileNm;
                }
                txt_attachFileNm.setValue(displayFileNm);

            }

        }

    }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name downloadAttach
 * @description 첨부파일 다운로드(그리드 셀 HTML 이 부르도록 window.disPage 에 노출).
 * @param {String} contnId 식별자
 * @param {Number} contnAttachSeq 일련번호
 * @returns {void}
 * @hidden N
 */
scwin.downloadAttach = function (contnId, contnAttachSeq) {
    const url = "/api/listing/listinvstg/common-board/file-download";
    const param = {
        contnId : contnId,
        contnAttachSeq : contnAttachSeq
    };
    $c.data.downFile(url, "", param);
};
